cat > src/main.rs << 'EOF'
mod cli;
mod client;
mod output;
mod request;
mod session;

use anyhow::{Context, Result};
use clap::Parser;
use std::io::IsTerminal;

use cli::Args;

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();

    // Initialize logging if debug is enabled
    if args.debug {
        tracing_subscriber::fmt()
            .with_env_filter(tracing_subscriber::EnvFilter::new("trace"))
            .init();
    }

    // Handle --generate
    if let Some(kind) = &args.generate {
        cli::generate_completion(kind)?;
        return Ok(());
    }

    // Handle special case: help command
    if args.url == "help" {
        cli::print_help();
        return Ok(());
    }

    // Parse the request
    let mut request = request::RequestBuilder::from_args(&args)
        .context("Failed to parse request")?;

    // Handle offline mode
    if args.offline {
        let output_str = request.format_as_http()?;
        println!("{}", output_str);
        return Ok(());
    }

    // Send the request
    let client = client::HttpClient::new(&args)?;
    let response = client.send(request).await?;

    // Handle output
    output::print_response(&response, &args)?;

    Ok(())
}
EOF

