use crate::cli::Args;
use anyhow::{Result, anyhow};
use std::collections::BTreeMap;
use url::Url;

pub struct RequestBuilder {
    pub method: String,
    pub url: String,
    pub headers: BTreeMap<String, String>,
    pub body: Option<String>,
    pub query_params: BTreeMap<String, String>,
}

impl RequestBuilder {
    pub fn from_args(args: &Args) -> Result<Self> {
        let mut builder = RequestBuilder {
            method: "GET".to_string(),
            url: args.url.clone(),
            headers: BTreeMap::new(),
            body: None,
            query_params: BTreeMap::new(),
        };

        // Parse the URL and method
        builder.parse_url_and_method()?;

        // Set default headers
        builder.set_default_headers();

        // Process request items
        builder.process_request_items(args)?;

        Ok(builder)
    }

    fn parse_url_and_method(&mut self) -> Result<()> {
        // Check if the URL contains a method (e.g., "POST http://example.com")
        let parts: Vec<&str> = self.url.split_whitespace().collect();
        if parts.len() == 2 {
            let possible_method = parts[0].to_uppercase();
            if is_valid_http_method(&possible_method) {
                self.method = possible_method;
                self.url = parts[1].to_string();
            }
        }

        // Normalize URL
        if !self.url.starts_with("http://") && !self.url.starts_with("https://") {
            if self.url.starts_with(":") {
                self.url = format!("http://localhost{}", self.url);
            } else if self.url.starts_with("://") {
                self.url = format!("http{}", self.url);
            } else {
                self.url = format!("http://{}", self.url);
            }
        }

        // Validate URL
        let _parsed = Url::parse(&self.url)?;

        Ok(())
    }

    fn set_default_headers(&mut self) {
        self.headers.insert("Accept-Encoding".to_string(), "gzip, deflate, br, zstd".to_string());
        self.headers.insert("User-Agent".to_string(), "xh/0.25.3".to_string());
        self.headers.insert("Connection".to_string(), "keep-alive".to_string());
        self.headers.insert("Accept".to_string(), "application/json, */*;q=0.5".to_string());
        self.headers.insert("Content-Type".to_string(), "application/json".to_string());
    }

    fn process_request_items(&mut self, args: &Args) -> Result<()> {
        let mut json_body = serde_json::json!({});
        let mut form_body = BTreeMap::new();
        let mut has_body_items = false;

        for item in &args.request_items {
            if let Some(colon_pos) = item.find(':') {
                // This is a header
                let key = &item[..colon_pos];
                let value = &item[colon_pos + 1..];

                if value.is_empty() {
                    // Remove header
                    self.headers.remove(key);
                } else {
                    self.headers.insert(key.to_string(), value.to_string());
                }
            } else if let Some(eq_pos) = item.find('=') {
                // This is a body field or query param
                let key = &item[..eq_pos];
                let value = &item[eq_pos + 1..];
                has_body_items = true;

                if args.json {
                    json_body[key] = serde_json::json!(value);
                }
            } else if let Some(eq_eq_pos) = item.find("==") {
                // This is a query param
                let key = &item[..eq_eq_pos];
                let value = &item[eq_eq_pos + 2..];
                self.query_params.insert(key.to_string(), value.to_string());
            }
        }

        // Set body if needed
        if has_body_items {
            self.body = Some(json_body.to_string());
            // Change method to POST if it was GET
            if self.method == "GET" {
                self.method = "POST".to_string();
            }
            // Update Content-Length
            if let Some(ref body) = self.body {
                self.headers.insert("Content-Length".to_string(), body.len().to_string());
            }
        }

        Ok(())
    }

    pub fn format_as_http(&self) -> Result<String> {
        let mut output = format!("{} {} HTTP/1.1\r\n", self.method, self.get_path_with_query());

        // Write headers
        for (key, value) in &self.headers {
            output.push_str(&format!("{}: {}\r\n", key, value));
        }

        output.push_str("\r\n");

        // Write body if present
        if let Some(ref body) = self.body {
            output.push_str(body);
            output.push('\n');
        }

        output.push('\n');

        Ok(output)
    }

    fn get_path_with_query(&self) -> String {
        let url = Url::parse(&self.url).unwrap();
        let path = if url.path().is_empty() { "/" } else { url.path() };
        path.to_string()
    }
}

fn is_valid_http_method(method: &str) -> bool {
    matches!(method, "GET" | "POST" | "PUT" | "DELETE" | "HEAD" | "OPTIONS" | "PATCH" | "CONNECT" | "TRACE")
}
