    pub generate: Option<String>,
    pub help: bool,
    pub version: bool,
}

pub fn parse_args(args: &[String]) -> Result<Args, String> {
    let mut parsed = Args {
        url: String::new(),
        request_items: Vec::new(),
        json: false,
        form: false,
        multipart: false,
        raw: None,
        pretty: None,
        format_options: None,
        style: None,
        response_charset: None,
        response_mime: None,
        print: None,
        headers: false,
        body: false,
        meta: false,
        verbose: 0,
        debug: false,
        all: false,
        history_print: None,
        quiet: 0,
        stream: false,
        compress: 0,
        output: None,
        download: false,
        continue_download: false,
        session: None,
        session_read_only: None,
        auth_type: None,
        auth: None,
        ignore_netrc: false,
        offline: false,
        check_status: false,
        follow: false,
        max_redirects: None,
        timeout: None,
        proxy: None,
        verify: None,
        cert: None,
        cert_key: None,
        ssl: None,
        https: false,
        http_version: None,
        resolve: None,
        interface: None,
        ipv4: false,
        ipv6: false,
        unix_socket: None,
        ignore_stdin: false,
        curl: false,
        curl_long: false,
        generate: None,
        help: false,
        version: false,
    };

    let mut i = 0;
    let mut url_found = false;

    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "-h" | "--help" => {
                parsed.help = true;
                return Ok(parsed);
            }
            "-V" | "--version" => {
                parsed.version = true;
                return Ok(parsed);
            }
            "--generate" => {
                i += 1;
                if i < args.len() {
                    parsed.generate = Some(args[i].clone());
                }
            }
            "-j" | "--json" => parsed.json = true,
            "-f" | "--form" => parsed.form = true,
            "--multipart" => parsed.multipart = true,
            "--raw" => {
                i += 1;
                if i < args.len() {
                    parsed.raw = Some(args[i].clone());
                } else {
                    return Err("--raw requires a value".to_string());
                }
            }
            "--pretty" => {
                i += 1;
                if i < args.len() {
                    parsed.pretty = Some(args[i].clone());
                }
            }
            "--format-options" => {
                i += 1;
                if i < args.len() {
                    parsed.format_options = Some(args[i].clone());
                }
            }
            "-s" | "--style" => {
                i += 1;
                if i < args.len() {
                    parsed.style = Some(args[i].clone());
                }
            }
            "--response-charset" => {
                i += 1;
                if i < args.len() {
                    parsed.response_charset = Some(args[i].clone());
                }
            }
            "--response-mime" => {
                i += 1;
                if i < args.len() {
                    parsed.response_mime = Some(args[i].clone());
                }
            }
            "-p" | "--print" => {
                i += 1;
                if i < args.len() {
                    parsed.print = Some(args[i].clone());
                }
            }
            "-h" | "--headers" => parsed.headers = true,
            "-b" | "--body" => parsed.body = true,
            "-m" | "--meta" => parsed.meta = true,
            "-v" | "--verbose" => parsed.verbose += 1,
            "--debug" => parsed.debug = true,
            "--all" => parsed.all = true,
            "-P" | "--history-print" => {
                i += 1;
                if i < args.len() {
                    parsed.history_print = Some(args[i].clone());
                }
            }
            "-q" | "--quiet" => parsed.quiet += 1,
            "-S" | "--stream" => parsed.stream = true,
            "-x" | "--compress" => parsed.compress += 1,
            "-o" | "--output" => {
                i += 1;
                if i < args.len() {
                    parsed.output = Some(PathBuf::from(&args[i]));
                }
            }
            "-d" | "--download" => parsed.download = true,
            "-c" | "--continue" => parsed.continue_download = true,
            "--session" => {
                i += 1;
                if i < args.len() {
                    parsed.session = Some(PathBuf::from(&args[i]));
                }
            }
            "--session-read-only" => {
                i += 1;
                if i < args.len() {
                    parsed.session_read_only = Some(PathBuf::from(&args[i]));
                }
            }
            "-A" | "--auth-type" => {
                i += 1;
                if i < args.len() {
                    parsed.auth_type = Some(args[i].clone());
                }
            }
            "-a" | "--auth" => {
                i += 1;
                if i < args.len() {
                    parsed.auth = Some(args[i].clone());
                }
            }
            "--ignore-netrc" => parsed.ignore_netrc = true,
            "--offline" => parsed.offline = true,
            "--check-status" => parsed.check_status = true,
            "-F" | "--follow" => parsed.follow = true,
            "--max-redirects" => {
                i += 1;
                if i < args.len() {
                    if let Ok(n) = args[i].parse() {
                        parsed.max_redirects = Some(n);
                    }
                }
            }
            "--timeout" => {
                i += 1;
                if i < args.len() {
                    if let Ok(n) = args[i].parse() {
                        parsed.timeout = Some(n);
                    }
                }
            }
            "--proxy" => {
                i += 1;
                if i < args.len() {
                    parsed.proxy = Some(args[i].clone());
                }
            }
            "--verify" => {
                i += 1;
                if i < args.len() {
                    parsed.verify = Some(args[i].clone());
                }
            }
            "--cert" => {
                i += 1;
                if i < args.len() {
                    parsed.cert = Some(PathBuf::from(&args[i]));
                }
            }
            "--cert-key" => {
                i += 1;
                if i < args.len() {
                    parsed.cert_key = Some(PathBuf::from(&args[i]));
                }
            }
            "--ssl" => {
                i += 1;
                if i < args.len() {
                    parsed.ssl = Some(args[i].clone());
                }
            }
            "--https" => parsed.https = true,
            "--http-version" => {
                i += 1;
                if i < args.len() {
                    parsed.http_version = Some(args[i].clone());
                }
            }
            "--resolve" => {
                i += 1;
                if i < args.len() {
                    parsed.resolve = Some(args[i].clone());
                }
            }
            "--interface" => {
                i += 1;
                if i < args.len() {
                    parsed.interface = Some(args[i].clone());
                }
            }
            "-4" | "--ipv4" => parsed.ipv4 = true,
            "-6" | "--ipv6" => parsed.ipv6 = true,
            "--unix-socket" => {
                i += 1;
                if i < args.len() {
                    parsed.unix_socket = Some(PathBuf::from(&args[i]));
                }
            }
            "-I" | "--ignore-stdin" => parsed.ignore_stdin = true,
            "--curl" => parsed.curl = true,
            "--curl-long" => parsed.curl_long = true,
            _ if arg.starts_with('-') => {
                return Err(format!("Unknown option: {}", arg));
            }
            _ => {
                if !url_found {
                    parsed.url = arg.clone();
                    url_found = true;
                } else {
                    parsed.request_items.push(arg.clone());
                }
            }
        }

        i += 1;
    }

    if !url_found && !parsed.help && !parsed.version && parsed.generate.is_none() {
        return Err("URL is required".to_string());
    }

    Ok(parsed)
}

pub fn print_help() {
    println!("xh is a friendly and fast tool for sending HTTP requests

Usage: executable [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...

Arguments:
  <[METHOD] URL>     The request URL, preceded by an optional HTTP method
  [REQUEST_ITEM]...  Optional key-value pairs to be included in the request.

Options:
  -j, --json
