use crate::cli::Args;
use std::collections::BTreeMap;

pub struct HttpRequest {
    pub method: String,
    pub url: String,
    pub headers: BTreeMap<String, String>,
    pub body: Option<String>,
}

pub fn build_offline_request(args: &Args) -> Result<String, String> {
    let mut request = parse_request(args)?;

    format_http_request(&request)
}

fn parse_request(args: &Args) -> Result<HttpRequest, String> {
    let mut request = HttpRequest {
        method: "GET".to_string(),
        url: args.url.clone(),
        headers: BTreeMap::new(),
        body: None,
    };

    // Parse URL and method
    parse_url_and_method(&mut request)?;

    // Set default headers
    request.headers.insert("Accept-Encoding".to_string(), "gzip, deflate, br, zstd".to_string());
    request.headers.insert("User-Agent".to_string(), "xh/0.25.3".to_string());
    request.headers.insert("Connection".to_string(), "keep-alive".to_string());
    request.headers.insert("Accept".to_string(), "application/json, */*;q=0.5".to_string());
    request.headers.insert("Content-Type".to_string(), "application/json".to_string());

    // Process request items
    process_request_items(args, &mut request)?;

    Ok(request)
}

fn parse_url_and_method(request: &mut HttpRequest) -> Result<(), String> {
    let parts: Vec<&str> = request.url.split_whitespace().collect();

    if parts.len() == 2 {
        let possible_method = parts[0].to_uppercase();
        if is_valid_http_method(&possible_method) {
            request.method = possible_method;
            request.url = parts[1].to_string();
        }
    }

    // Normalize URL
    if !request.url.starts_with("http://") && !request.url.starts_with("https://") {
        if request.url.starts_with(":") {
            request.url = format!("http://localhost{}", request.url);
        } else if request.url.starts_with("://") {
            request.url = format!("http{}", request.url);
        } else {
            request.url = format!("http://{}", request.url);
        }
    }

    Ok(())
}

fn process_request_items(args: &Args, request: &mut HttpRequest) -> Result<(), String> {
    let mut json_body = JsonValue::Object(BTreeMap::new());
    let mut has_body_items = false;

    for item in &args.request_items {
        // Check for header with empty value (unset header)
        if item.ends_with(":") && !item.ends_with("::") {
            let key = &item[..item.len()-1];
            request.headers.remove(key);
            continue;
        }

        // Check for header with empty string value
        if item.ends_with(";") && !item.ends_with(";;") {
            let key = &item[..item.len()-1];
            request.headers.insert(key.to_string(), String::new());
            continue;
        }

        // Check for query string (==)
        if let Some(pos) = item.find("==") {
            let key = &item[..pos];
            let value = &item[pos + 2..];
            // Add to URL as query param
            if !request.url.contains('?') {
                request.url.push('?');
            } else {
                request.url.push('&');
            }
            request.url.push_str(&format!("{}={}", key, value));
            continue;
        }

        // Check for JSON literal (: followed by =)
        if let Some(pos) = item.find(":=") {
            let key = &item[..pos];
            let value_str = &item[pos + 2..];
            has_body_items = true;

            if args.json {
                let value = parse_json_value(value_str)?;
                if let JsonValue::Object(ref mut map) = json_body {
                    map.insert(key.to_string(), value);
                }
            }
            continue;
        }

        // Check for regular body field or header (=)
        if let Some(pos) = item.find('=') {
            // Check if it's a header (contains a colon before the equals)
            if !item.contains(':') || item.find(':').unwrap_or(usize::MAX) > pos {
                // It's a body field
                let key = &item[..pos];
                let value = &item[pos + 1..];
                has_body_items = true;

                if args.json {
                    if let JsonValue::Object(ref mut map) = json_body {
                        map.insert(key.to_string(), JsonValue::String(value.to_string()));
                    }
                }
                continue;
            }
        }

        // Check for header (contains :)
        if let Some(pos) = item.find(':') {
            let key = &item[..pos];
            let value = &item[pos + 1..];
            request.headers.insert(key.to_string(), value.to_string());
            continue;
        }
    }

    // Set body if needed
    if has_body_items {
        let body_str = match json_body {
            JsonValue::Object(map) => {
                json_encode_object(&map)
            }
            _ => "{}".to_string(),
        };
        request.body = Some(body_str.clone());

        // Update method to POST if still GET
        if request.method == "GET" {
            request.method = "POST".to_string();
        }

        // Update Content-Length
        request.headers.insert("Content-Length".to_string(), body_str.len().to_string());
    }

    Ok(())
}

enum JsonValue {
    String(String),
    Number(f64),
    Boolean(bool),
    Array(Vec<JsonValue>),
    Object(BTreeMap<String, JsonValue>),
    Null,
}

fn parse_json_value(s: &str) -> Result<JsonValue, String> {
    let trimmed = s.trim();

    if trimmed == "null" {
        return Ok(JsonValue::Null);
    }

    if trimmed == "true" {
        return Ok(JsonValue::Boolean(true));
    }

    if trimmed == "false" {
        return Ok(JsonValue::Boolean(false));
    }

    if trimmed.starts_with('[') && trimmed.ends_with(']') {
        // Try to parse as array
        return Ok(JsonValue::Array(Vec::new())); // Simplified
    }

    if trimmed.starts_with('{') && trimmed.ends_with('}') {
        // Try to parse as object
        return Ok(JsonValue::Object(BTreeMap::new())); // Simplified
    }

    if let Ok(n) = trimmed.parse::<f64>() {
        return Ok(JsonValue::Number(n));
    }

    Ok(JsonValue::String(trimmed.to_string()))
}

fn json_encode_object(map: &BTreeMap<String, JsonValue>) -> String {
    let mut result = String::from("{");
    let mut first = true;

    for (key, value) in map {
        if !first {
            result.push(',');
        }
        first = false;

        result.push('"');
        result.push_str(&escape_json_string(key));
        result.push_str("\":");
        result.push_str(&json_encode_value(value));
    }

    result.push('}');
    result
}

fn json_encode_value(value: &JsonValue) -> String {
    match value {
        JsonValue::String(s) => {
            format!("\"{}\"", escape_json_string(s))
        }
        JsonValue::Number(n) => n.to_string(),
        JsonValue::Boolean(b) => b.to_string(),
        JsonValue::Null => "null".to_string(),
        JsonValue::Array(_) => "[]".to_string(), // Simplified
        JsonValue::Object(_) => "{}".to_string(), // Simplified
    }
}

fn escape_json_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            _ => result.push(c),
        }
    }
    result
}

fn format_http_request(request: &HttpRequest) -> Result<String, String> {
    let mut output = String::new();

    // Add request line
    let path = extract_path(&request.url);
    output.push_str(&format!("{} {} HTTP/1.1\r\n", request.method, path));

    // Add headers
    for (key, value) in &request.headers {
        output.push_str(&format!("{}: {}\r\n", key, value));
    }

    // Add Host header if not already present
    if !request.headers.contains_key("Host") {
        if let Some(host) = extract_host(&request.url) {
            output.push_str(&format!("Host: {}\r\n", host));
        }
    }

    output.push_str("\r\n");

    // Add body if present
    if let Some(ref body) = request.body {
        output.push_str(body);
        output.push('\n');
    }

    output.push('\n');

    Ok(output)
}

fn extract_path(url: &str) -> String {
    // Remove scheme
    let after_scheme = if let Some(pos) = url.find("://") {
        &url[pos + 3..]
    } else {
        url
    };

    // Skip host
    let after_host = if let Some(pos) = after_scheme.find('/') {
        &after_scheme[pos..]
    } else {
        "/"
    };

    after_host.to_string()
}

fn extract_host(url: &str) -> Option<String> {
    // Remove scheme
    let after_scheme = if let Some(pos) = url.find("://") {
        &url[pos + 3..]
    } else {
        url
    };

    // Get host part
    let host = if let Some(pos) = after_scheme.find('/') {
        &after_scheme[..pos]
    } else {
        after_scheme
    };

    Some(host.to_string())
}

fn is_valid_http_method(method: &str) -> bool {
    matches!(method,
        "GET" | "POST" | "PUT" | "DELETE" | "HEAD" | "OPTIONS" |
        "PATCH" | "CONNECT" | "TRACE"
    )
}
