                return Err(format!("Unknown option: {}", arg));
            }
            _ => {
                // This is a positional argument
                // Could be METHOD URL, URL, or request item
                if !url_found {
                    // Check if this might be a METHOD
                    let upper = arg.to_uppercase();
                    if is_valid_http_method(&upper) && i + 1 < args.len() {
                        // It might be a method, check if next arg looks like a URL
                        let next_arg = &args[i + 1];
                        if looks_like_url(next_arg) {
                            // This is METHOD URL pattern
                            parsed.url = format!("{} {}", upper, next_arg);
                            url_found = true;
                            i += 1; // Skip the next arg since we already processed it
                        } else {
                            // Just a URL that happens to be named like a method
                            parsed.url = arg.clone();
                            url_found = true;
                        }
                    } else {
                        parsed.url = arg.clone();
                        url_found = true;
                    }
                } else {
                    parsed.request_items.push(arg.clone());
                }
            }
        }

        i += 1;
    }

    if !url_found && !parsed.help && !parsed.version && parsed.generate.is_none() {
        return Err("URL is required".to_string());
    }

    Ok(parsed)
}

fn is_valid_http_method(method: &str) -> bool {
    matches!(method,
        "GET" | "POST" | "PUT" | "DELETE" | "HEAD" | "OPTIONS" |
        "PATCH" | "CONNECT" | "TRACE"
    )
}

fn looks_like_url(s: &str) -> bool {
    s.contains("://") || s.contains(".") || s.contains(":") || s.starts_with("localhost") || s.starts_with("/") || s.starts_with(":")
}

