    }
}

fn escape_json_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            _ => result.push(c),
        }
    }
    result
}

fn format_http_request(request: &HttpRequest) -> Result<String, String> {
    let mut output = String::new();

    // Add request line
    let path = extract_path(&request.url);
    output.push_str(&format!("{} {} HTTP/1.1\n", request.method, path));

    // Add headers in the order that matches reference
    let header_order = vec![
        "Accept-Encoding",
        "User-Agent",
        "Connection",
        "Accept",
        "Content-Type",
        "Content-Length",
