            let key = &item[..item.len()-1];
            // Remove all case-insensitive matches
            let key_lower = key.to_lowercase();
            request.headers.retain(|k, _| k.to_lowercase() != key_lower);
            continue;
        }

        // Check for header with empty string value
        if item.ends_with(";") && !item.ends_with(";;") {
            let key = &item[..item.len()-1];
            request.headers.insert(key.to_string(), String::new());
            request.has_custom_headers = true;
            continue;
        }

        // Check for query string (==) - must check before single =
        if let Some(pos) = item.find("==") {
            let key = &item[..pos];
            let value = &item[pos + 2..];
            // Add to URL as query param
            if !request.url.contains('?') {
                request.url.push('?');
            } else {
                request.url.push('&');
            }
            request.url.push_str(&format!("{}={}", key, value));
            continue;
        }

        // Check for JSON literal (: followed by =) - must check before single =
        if let Some(pos) = item.find(":=") {
            let key = &item[..pos];
            let value_str = &item[pos + 2..];
            has_body_items = true;

            if args.json {
                let value = parse_json_value(value_str)?;
                json_body_items.push((key.to_string(), value));
            }
            continue;
        }

        // Check for regular body field (=) - must check before (:)
        if let Some(eq_pos) = item.find('=') {
            // Make sure this isn't part of := or ==
            if eq_pos > 0 && &item[eq_pos-1..eq_pos] != ":" {
                // It's a body field
                let key = &item[..eq_pos];
                let value = &item[eq_pos + 1..];
                has_body_items = true;

                if args.json {
                    json_body_items.push((key.to_string(), JsonValue::String(value.to_string())));
                }
                continue;
            }
        }

        // Check for header (contains : but not part of := or ==)
        if let Some(colon_pos) = item.find(':') {
            // Make sure it's not part of := or ::
            if colon_pos + 1 < item.len() && &item[colon_pos+1..colon_pos+2] != "=" {
                let key = &item[..colon_pos];
                let value = &item[colon_pos + 1..];
                request.has_custom_headers = true;
                // Remove old value with case-insensitive match
                let key_lower = key.to_lowercase();
                request.headers.retain(|k, _| k.to_lowercase() != key_lower);
                // Add new value
                request.headers.insert(key.to_string(), value.to_string());
                continue;
            }
        }
    }

    // Set body if needed
    if has_body_items {
        let body_str = json_encode_object_ordered(&json_body_items);
        request.body = Some(body_str);

        // Update method to POST if still GET
        if request.method == "GET" {
            request.method = "POST".to_string();
        }
    }

    Ok(())
}

enum JsonValue {
    String(String),
    Number(f64),
    Boolean(bool),
    #[allow(dead_code)]
    Array(Vec<JsonValue>),
    #[allow(dead_code)]
    Object(Vec<(String, JsonValue)>),
    Null,
}

fn parse_json_value(s: &str) -> Result<JsonValue, String> {
    let trimmed = s.trim();

    if trimmed == "null" {
        return Ok(JsonValue::Null);
    }

    if trimmed == "true" {
        return Ok(JsonValue::Boolean(true));
    }

    if trimmed == "false" {
        return Ok(JsonValue::Boolean(false));
    }

    if trimmed.starts_with('[') && trimmed.ends_with(']') {
        // Try to parse as array
        return Ok(JsonValue::Array(Vec::new())); // Simplified
    }

    if trimmed.starts_with('{') && trimmed.ends_with('}') {
        // Try to parse as object
        return Ok(JsonValue::Object(Vec::new())); // Simplified
    }

    if let Ok(n) = trimmed.parse::<f64>() {
        return Ok(JsonValue::Number(n));
    }

    Ok(JsonValue::String(trimmed.to_string()))
}

fn json_encode_object_ordered(items: &[(String, JsonValue)]) -> String {
    let mut result = String::from("{");
    let mut first = true;

    for (key, value) in items {
        if !first {
            result.push(',');
        }
        first = false;

        result.push('"');
        result.push_str(&escape_json_string(key));
        result.push_str("\":");
        result.push_str(&json_encode_value(value));
    }

    result.push('}');
    result
}

fn json_encode_value(value: &JsonValue) -> String {
    match value {
        JsonValue::String(s) => {
            format!("\"{}\"", escape_json_string(s))
        }
        JsonValue::Number(n) => {
            if n.fract() == 0.0 {
                format!("{}", *n as i64)
            } else {
                n.to_string()
            }
        }
        JsonValue::Boolean(b) => b.to_string(),
        JsonValue::Null => "null".to_string(),
        JsonValue::Array(_) => "[]".to_string(), // Simplified
        JsonValue::Object(_) => "{}".to_string(), // Simplified
    }
}

fn escape_json_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            _ => result.push(c),
        }
    }
    result
}

fn format_http_request(request: &HttpRequest) -> Result<String, String> {
    let mut output = String::new();

    // Add request line
    let path = extract_path(&request.url);
    output.push_str(&format!("{} {} HTTP/1.1\n", request.method, path));

    // Add headers in the order that matches reference
    let header_order = vec![
        "Accept-Encoding",
        "User-Agent",
        "Connection",
        "Accept",
        "Content-Type",
        "Content-Length",
    ];

    for header_name in &header_order {
        // Find header with case-insensitive match
        for (key, value) in &request.headers {
            if key.to_lowercase() == header_name.to_lowercase() {
                output.push_str(&format!("{}: {}\n", header_name, value));
                break;
            }
        }
    }

    // Add any remaining headers not in the order list
    for (key, value) in &request.headers {
        let key_lower = key.to_lowercase();
        if !header_order.iter().any(|h| h.to_lowercase() == key_lower) {
            output.push_str(&format!("{}: {}\n", key, value));
        }
    }

    // Add Host header
    if let Some(host) = extract_host(&request.url) {
        output.push_str(&format!("Host: {}\n", host));
    }

    output.push_str("\n");

    // Add body if present
    if let Some(ref body) = request.body {
        output.push_str(body);
        output.push_str("\n");
    } else {
        // No body, add extra newline
        output.push_str("\n");
    }

    output.push_str("\n");

    Ok(output)
}

fn extract_path(url: &str) -> String {
    // Remove scheme
    let after_scheme = if let Some(pos) = url.find("://") {
        &url[pos + 3..]
    } else {
        url
    };

    // Skip host
    let after_host = if let Some(pos) = after_scheme.find('/') {
        &after_scheme[pos..]
    } else {
        "/"
    };

    after_host.to_string()
}

fn extract_host(url: &str) -> Option<String> {
    // Remove scheme
    let after_scheme = if let Some(pos) = url.find("://") {
        &url[pos + 3..]
    } else {
        url
    };

    // Get host part
    let host = if let Some(pos) = after_scheme.find('/') {
        &after_scheme[..pos]
    } else {
        after_scheme
    };

    Some(host.to_string())
}

fn is_valid_http_method(method: &str) -> bool {
    matches!(method,
        "GET" | "POST" | "PUT" | "DELETE" | "HEAD" | "OPTIONS" |
        "PATCH" | "CONNECT" | "TRACE"
    )
}
